import*as Platform from"../../../core/platform/platform.js";import*as Types from"../types/types.js";const updateCountersByProcess=new Map;export function reset(){updateCountersByProcess.clear()}export function handleEvent(e){if(Types.TraceEvents.isTraceEventUpdateCounters(e)){const t=Platform.MapUtilities.getWithDefault(updateCountersByProcess,e.pid,(()=>[]));t.push(e),updateCountersByProcess.set(e.pid,t)}}export function data(){return{updateCountersByProcess:new Map(updateCountersByProcess)}}